import abc
import re

import six
from moler.cmd.commandtextualgeneric import CommandTextualGeneric

__author__ = "Yeshu Yang, Michal Ernst, Marcin Usielski"
__copyright__ = "Copyright (C) 2018-2024, Nokia"
__email__ = "yeshu.yang@nokia-sbell.com, michal.ernst@nokia.com, marcin.usielski@nokia.com"


@six.add_metaclass(abc.ABCMeta)
class GenericRtg(CommandTextualGeneric):
    """Genericrtg command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Genericrtg command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        if not prompt:
            prompt = r"RTG>|CUS>"
        super(GenericRtg, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.re_fail = re.compile(r"ERROR|Invalid command")

    _re_timestamp_2_remove = re.compile(r"^\s*(\d{2}\.\d{2}:\d{2}:\d{2}\.\d+\|\s)")

    def _process_line_from_command(self, current_chunk, line, is_full_line):
        """
        Process line from command.

        :param current_chunk: Chunk of line sent by connection.
        :param line: Line of output (current_chunk plus previous chunks of this line - if any) without newline char(s).
        :param is_full_line: True if line had newline char(s). False otherwise.
        :return: None.
        """
        decoded_line = self._decode_line(line=line)
        line = re.sub(GenericRtg._re_timestamp_2_remove, "", decoded_line)
        self.on_new_line(line=line, is_full_line=is_full_line)
